  const STALE = "2026-07-20T00:00:00Z";
  const fresh = buildBsolReadOnlyReviewCandidateDisplay({ checkedAt: FRESH });
  const stale = buildBsolReadOnlyReviewCandidateDisplay({ checkedAt: STALE });
